/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';

const disposable = mkdtempSync(join(process.cwd(), '.catalog-review-'));
const initial = [
  { id: 'a', title: 'Альфа', pinned: false },
  { id: 'b', title: 'Beta', pinned: true },
  { id: 'c', title: 'Gamma', pinned: true },
  { id: 'd', title: 'Delta' },
];
const loadedInitial = initial.map(card => ({ ...card, pinned: card.pinned ?? false }));
const shared = \"import { loadCatalog, setPinned, saveCatalog } from './catalog/src/catalog.mjs';\";
function run(body, path, ...args) {
  const result = spawnSync(process.execPath, ['--input-type=module', '-e', shared + body, path, ...args], { encoding: 'utf8' });
  if (result.error) throw result.error;
  assert.equal(result.status, 0, result.stderr);
  return JSON.parse(result.stdout);
}
function check(label, actual, expected) {
  try {
    assert.deepEqual(actual, expected);
    console.log('PASS', label, JSON.stringify(actual));
  } catch {
    console.log('FAIL', label, JSON.stringify({ expected, actual }));
  }
}

try {
  const legacyPath = join(disposable, 'legacy.json');
  writeFileSync(legacyPath, JSON.stringify(initial));
  const reopened = 'console.log(JSON.stringify({ pid: process.pid, cards: loadCatalog(process.argv[1]) }));';
  check('loadCatalog / legacy and explicit booleans', run(reopened, legacyPath).cards, loadedInitial);

  for (const [name, id, pinned] of [['pin', 'a', true], ['unpin', 'b', false]]) {
    const path = join(disposable, name + '.json');
    writeFileSync(path, JSON.stringify(initial));
    const expected = loadedInitial.map(card => card.id === id ? { ...card, pinned } : card);
    const first = run(
      'const [path, id, pinned] = process.argv.slice(1); const cards = setPinned(loadCatalog(path), id, pinned === \"true\"); saveCatalog(path, cards); console.log(JSON.stringify({ pid: process.pid, cards }));',
      path, id, String(pinned),
    );
    const second = run(reopened, path);
    assert.notEqual(first.pid, second.pid);
    const onDisk = JSON.parse(readFileSync(path, 'utf8'));
    check(name + ' / before close', first.cards, expected);
    check(name + ' / file contents', onDisk, expected);
    check(name + ' / target after reopen', second.cards.find(card => card.id === id), expected.find(card => card.id === id));
    check(name + ' / id order and titles after reopen',
      second.cards.map(({ id, title }) => ({ id, title })),
      expected.map(({ id, title }) => ({ id, title })),
    );
    check(name + ' / other cards after reopen', second.cards.filter(card => card.id "'!== id), expected.filter(card => card.id !== id));
  }

  const rejected = run(
    '"'try { setPinned(loadCatalog(process.argv[1]), \"missing\", true); console.log(JSON.stringify({ accepted: true })); } catch (error) { console.log(JSON.stringify({ name: error.name, message: error.message })); }',
    legacyPath,
  );
  check('missing id / nonempty on-disk catalog', rejected, { name: 'Error', message: 'Unknown card: missing' });
} finally {
  rmSync(disposable, { recursive: true });
}
NODE"

